// Gelen body'den soruyu normalize et
const payload = $json.body ?? $json;
const msg = String(
  payload.message ||
  payload.query ||
  payload.text ||
  ''
).trim();
const mode = String(payload.mode || 'auto').trim();

return [{
  json: {
    ...payload,
    original_message: msg,
    query: msg,
    text: msg,
    mode,
    // Arama scriptine gönderilecek kelimeler (max 8)
    words: msg
      .split(/\s+/)
      .map(w => w.trim())
      .filter(Boolean)
      .slice(0, 8)
  }
}];

const stdout = $input.first().json.stdout || '';
const stderr = $input.first().json.stderr || '';
try {
  const parsed = JSON.parse(stdout);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: {
    ok: false,
    query: '',
    query_terms: [],
    result_count: 0,
    results: [],
    error: `parse hatası: ${e.message}`,
    raw_stdout: stdout,
    raw_stderr: stderr
  } }];
}

const query   = $json.query || '';
const results = ($json.results || []).slice(0, 3);

// Model için context — artık gerçek PDF adı ve sayfa var
const context = results.map((r, i) => {
  return [
    `[KAYNAK ${i + 1}]`,
    `PDF  : ${r.pdf_file   || r.manual_name || '-'}`,
    `Sayfa: ${r.page ?? '?'}`,
    `Skor : ${r.score}`,
    ``,
    r.text
  ].join('\n');
}).join('\n\n─────────────────────\n\n');

return [{
  json: {
    query,
    raw_results: $json.results || [],
    prompt: `Sen teknik gemi manual arama asistanısın.
SADECE verilen kaynaklara dayanarak cevap ver. Uydurma yapma.
Bilgi yoksa açıkça söyle.
Kısa, net ve teknik yaz.

Kullanıcı sorusu:
${query}

Kaynaklar:
${context}

Sadece JSON döndür:
{ "summary": "kısa teknik cevap", "confidence": "high|medium|low" }`
  }
}];

parameters.body:
={{ JSON.stringify({
  model: "claude-sonnet-4-6",
  max_tokens: 1024,
  system: "Teknik gemi manual asistanısın. Sadece geçerli JSON döndür. Markdown yok.",
  messages: [{ role: "user", content: $json.prompt }]
}) }}

parameters.jsCode:
const modelOutput = $input.first().json;
// Claude API response: content[0].text
const raw = modelOutput?.content?.[0]?.text ||
            modelOutput?.text ||
            modelOutput?.content ||
            modelOutput?.response || '';

let parsed;
try {
  parsed = JSON.parse(String(raw).trim());
} catch (e) {
  // JSON parse başarısız — ham metni kullan
  parsed = {
    summary:    String(raw).trim() || 'Özet üretilemedi.',
    confidence: 'low'
  };
}

// parse node'dan ham sonuçları al
const parseData  = $('parse').first().json;
const rawResults = parseData.results || [];
const query      = parseData.query   || '';

// Kullanıcıya gösterilecek kaynak listesi
// ARTIK: pdf_file + page  (chunk_id, skor vs. kullanıcıya gösterilmez)
const sources = rawResults.map((r, i) => ({
  index:       i + 1,
  pdf_file:    r.pdf_file    || (r.manual_name ? r.manual_name + '.pdf' : '-'),
  manual_name: r.manual_name || '-',
  page:        r.page        ?? null,
  score:       r.score       // sadece debug için; HTML'de gösterilmez
}));

return [{
  json: {
    ok:         true,
    query,
    summary:    parsed.summary    || 'Özet üretilemedi.',
    confidence: parsed.confidence || 'low',
    sources,
    raw_results: rawResults
  }
}];

return [{
  json: {
    ok:         false,
    query:      $json.query || '',
    summary:    $json.error || 'Bu konuda dokümanlarda bilgi bulunamadı.',
    confidence: 'low',
    sources:    [],
    raw_results: $json.results || []
  }
}];

parameters.responseBody:
={{ JSON.stringify({
  text: $json.summary || 'Cevap yok.',

  // Kullanıcıya sadece "Kaynak: X.pdf | Sayfa: Y" göster
  sources: Array.isArray($json.sources) && $json.sources.length
    ? $json.sources
        .map(s => `Kaynak: ${s.pdf_file} | Sayfa: ${s.page ?? '?'}`)
        .join('\n')
    : 'Kaynak bulunamadı.',

  ok:         $json.ok         ?? false,
  query:      $json.query      || '',
  confidence: $json.confidence || 'low'
}) }}

